var EXTRA=[{"dot": "gray", "j": "Asia Pac J Sports Med Arthrosc Rehabil Technol", "h": "Osteotomia tibiale aperta: togliere la placca migliora dolore e soddisfazione", "v": "Coorte prospettica di pazienti consecutivi, valutati a tre mesi e senza gruppo di controllo: il miglioramento può dipendere anche dall'aspettativa e non isola l'effetto della rimozione.", "pmid": "42898098", "doi": "10.1016/j.asmart.2026.09.003", "temi": ["osteotomia", "placca", "rimozione", "soddisfazione"]}, {"dot": "gray", "j": "BMC Musculoskelet Disord", "h": "Infezione dopo osteotomia del ginocchio: pelle, fegato ed emoglobina come fattori", "v": "Studio retrospettivo multicentrico con pochi eventi: le associazioni vanno confermate prima di guidare la selezione, e l'infezione è definita da un nuovo intervento di pulizia.", "pmid": "42897581", "doi": "10.1186/s12891-026-10277-2", "temi": ["osteotomia", "infezione", "fattori di rischio", "multicentrico"]}, {"dot": "gray", "j": "Arthrosc Tech", "h": "Radice meniscale e osteotomia insieme: tecnica con guide stampate in 3D", "v": "Descrizione tecnica senza pazienti né esiti: mostra come pianificare tunnel transtibiale e osteotomia per evitare il conflitto, non se il risultato è migliore.", "pmid": "42889858", "doi": "10.1002/atn2.70323", "temi": ["radice meniscale", "osteotomia", "transtibiale", "stampa 3D"]}, {"dot": "gray", "j": "Phys Ther Sport", "h": "Dopo LCA, l'esercizio del piede corto controlla meglio il valgo in atterraggio", "v": "Studio randomizzato esplorativo, piccolo e senza esiti di nuova rottura: misura il movimento in laboratorio, non se le persone si infortunano meno.", "pmid": "42913286", "doi": "10.1016/j.ptsp.2026.102002", "temi": ["LCA", "riabilitazione", "atterraggio", "piede"]}, {"dot": "gray", "j": "Br Med Bull", "h": "Lesioni da stress della fisi del ginocchio negli atleti giovani: prove scarse", "v": "Revisione sistematica di soli casi riportati: aiuta a riconoscere un quadro radiografico spesso sottile, non a scegliere durata o tipo di trattamento.", "pmid": "42911874", "doi": "10.1093/bmb/ldag036", "temi": ["fisi", "atleti giovani", "stress", "risonanza"]}, {"dot": "gray", "j": "Rev Esp Cir Ortop Traumatol", "h": "Crociato: tendine peroneo lungo contro hamstring, esiti simili a due anni", "v": "Studio retrospettivo piccolo di un solo chirurgo: non riguarda il tuo innesto e non dimostra equivalenza.", "pmid": "42918446", "doi": "10.1016/j.recot.2026.10.014", "temi": ["LCA", "peroneo lungo", "hamstring", "innesto"]}, {"dot": "gray", "j": "Indian J Orthop", "h": "Prelievo del peroneo lungo per il LCA: la funzione della caviglia non cala", "v": "Serie di livello IV senza gruppo di controllo, in pazienti con attività bassa o moderata; non riguarda il tuo innesto.", "pmid": "42894519", "doi": "10.1007/s43465-026-01884-1", "temi": ["LCA", "peroneo lungo", "caviglia", "prelievo"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Tutore scaricatore nell'artrosi: commento al consensus Delphi di Arthroscopy", "v": "Editoriale di opinione su un consensus già uscito: non porta dati nuovi.", "pmid": "42910729", "doi": "10.1002/arj.70673", "temi": ["tutore", "artrosi", "Delphi", "consensus"]}, {"dot": "gray", "j": "Arthroplasty", "h": "Antibiotico intraosseo nella protesi robotica: concentrazioni nel tessuto più alte", "v": "RCT piccolo che misura i livelli del farmaco e non le infezioni: serve uno studio sugli esiti prima di cambiare la profilassi.", "pmid": "42894257", "doi": "10.1186/s42836-026-00436-0", "temi": ["protesi", "robotica", "antibiotico", "profilassi"]}];
var SCOPERTE=[{"t": "Perché il crociato si rompe prima che il riflesso possa intervenire: un modello con la titina", "v": "Fisiologia dello sport (Int J Sports Phys Ther, gruppo europeo): un commento teorico propone che la protezione dipenda dalla tensione degli hamstring decisa prima del contatto con il suolo e dalla rigidità della titina, la proteina elastica del muscolo, e non dai riflessi. Vale la deviazione perché sposta lo sguardo dal controllo in atterraggio al muscolo come molla; è un'ipotesi di livello 5 e non un dato, senza pazienti.", "pmid": "42893121", "doi": "10.26603/001c.163662", "temi": ["LCA", "prevenzione", "titina", "biofisica"]}, {"t": "Ultrasuoni sulla cartilagine: un modello al computer cerca la frequenza giusta per ogni ginocchio", "v": "Bioingegneria (Biomech Model Mechanobiol, Università del Minho, Portogallo): una rete neurale accelera la simulazione di come le onde acustiche attraversano il ginocchio e deformano il nucleo del condrocita, con bande di frequenza diverse nel ginocchio sano e in quello artrosico. Vale la deviazione perché propone di scegliere la frequenza dalla meccanica della cellula e non per tentativi; è una simulazione su pochi ginocchi, senza esperimento né pazienti.", "pmid": "42891756", "doi": "10.1007/s10237-026-02138-7", "temi": ["cartilagine", "ultrasuoni", "intelligenza artificiale", "bioingegneria"]}, {"t": "Il «coltello ad ago» a visione diretta per l'artrosi di ginocchio: la metanalisi dalla Cina", "v": "Medicina tradizionale cinese (Indian J Orthop, Università di medicina tradizionale cinese del Fujian): metanalisi di studi randomizzati sul rilascio con «visual needle knife», confrontato con altre tecniche d'ago, agopuntura e acido ialuronico. Vale la deviazione perché è un tipo di intervento del mondo orientale, il buco che hai dichiarato; gli autori concludono per una diffusione che comparatori eterogenei e un abstract senza valutazione del rischio di bias non autorizzano.", "pmid": "42894552", "doi": "10.1007/s43465-026-01836-9", "temi": ["artrosi", "medicina tradizionale cinese", "ago", "mondo orientale"]}];
var SOC={"2": {"video": "Protesi su una parte del ginocchio: il robot riduce i reinterventi? Una revisione di 34 studi su oltre 68.000 protesi ha confrontato l'intervento con il robot e quello manuale.\n\nCon il robot ci sono stati meno reinterventi e meno complicanze, e il piatto tibiale è risultato posizionato più vicino al piano; l'operazione dura circa sedici minuti di più.\n\nIl limite: quasi tutti gli studi non assegnano i pazienti a caso e seguono i pazienti in media due anni.\nFonte: PubMed, PMID 42908376.", "linkedin": "UKA robotica contro manuale: meno revisioni (OR 0,54; IC 95% 0,39-0,75) e meno complicanze (OR 0,66; IC 95% 0,44-0,99) in una metanalisi di 34 studi (Orthop Surg, 2026).\n\nIl limite: 27 studi su 34 non randomizzati, controllo medio di due anni, nessuna soglia MCID specifica per la UKA.\nFonte: PubMed, PMID 42908376.", "instagram": "Protesi parziale e robot\n\nIn 34 studi, con il robot meno reinterventi e meno complicanze.\n\nStudi non casuali, controllo di circa due anni.\nFonte: PubMed, PMID 42908376.", "pazienti": "Protesi su una parte del ginocchio: il robot aiuta? Una revisione di 34 studi ha confrontato l'intervento con il robot e quello senza. Con il robot sono stati meno frequenti i reinterventi e le complicanze, e l'impianto è risultato posizionato in modo un po' più preciso.\n\nI pazienti sono stati seguiti in media per due anni: servono controlli più lunghi. La scelta dipende dal caso.\nFonte: PubMed, PMID 42908376."}};
var SOCV={"2": {"video": {"chir": ["Protesi monocompartimentale robotica contro manuale: metanalisi di 34 studi su Orthopaedic Surgery, 68.196 protesi, controllo medio di circa due anni, testo completo letto.", "Revisioni OR 0,54 (IC 95% 0,39-0,75), complicanze OR 0,66 (IC 95% 0,44-0,99), pendenza tibiale più vicina all'obiettivo di 1,75° (IC 95% da 1,07 a 2,44). KSS ginocchio +2,49 (p=0,007); tempo operatorio più lungo di 16,1 minuti.", "Limiti: 27 studi su 34 non randomizzati, eterogeneità alta su pendenza tibiale e degenza, nessuna soglia MCID specifica per la monocompartimentale. Il vantaggio sulle revisioni a due anni non prova una migliore sopravvivenza dell'impianto.\nFonte: PubMed, PMID 42908376."], "misto": ["Protesi che sostituisce solo una parte del ginocchio: con l'aiuto del robot l'impianto dura di più? Una revisione di 34 studi ha confrontato robot e tecnica manuale su oltre 68.000 protesi.", "Con il robot ci sono stati meno reinterventi (odds ratio 0,54, intervallo di confidenza da 0,39 a 0,75) e meno complicanze, e il piatto tibiale è risultato più vicino alla pendenza pianificata. L'operazione dura circa sedici minuti di più.", "Il limite: quasi tutti gli studi non assegnano i pazienti a caso e seguono i pazienti in media due anni; i punteggi di funzione migliorano di poco, meno di quanto si considera percepibile per una protesi totale.\nFonte: PubMed, PMID 42908376."], "pazienti": ["Protesi su una parte del ginocchio: serve il robot? Una grande revisione di 34 studi ha confrontato l'intervento con il robot e quello senza.", "Con il robot sono stati meno frequenti i reinterventi e le complicanze, e l'impianto è risultato posizionato in modo un po' più preciso. L'intervento dura qualche minuto di più.", "Gli studi seguono i pazienti in media per due anni e la maggior parte non assegna i pazienti a caso: servono controlli più lunghi. La scelta dipende dal caso e dal chirurgo.\nFonte: PubMed, PMID 42908376."]}, "linkedin": {"chir": ["UKA robotica contro manuale: metanalisi di 34 studi (Orthop Surg, 2026; 68.196 protesi, controllo medio circa 2 anni). Revisioni OR 0,54 (IC 95% 0,39-0,75), complicanze OR 0,66 (IC 95% 0,44-0,99).", "Pendenza tibiale più vicina all'obiettivo di 1,75° (IC 95% da 1,07 a 2,44); KSS ginocchio +2,49 (p=0,007), sotto le soglie MCID note per la protesi totale; tempo operatorio +16,1 minuti.", "Il limite: 27 studi su 34 non randomizzati, eterogeneità alta, nessuna soglia MCID validata per la UKA; il vantaggio sulle revisioni a due anni non prova una migliore sopravvivenza.\nFonte: PubMed, PMID 42908376."], "misto": ["Protesi parziale di ginocchio con il robot: meno reinterventi, ma con prove ancora limitate. Revisione di 34 studi su 68.196 protesi (Orthop Surg, 2026).", "Reinterventi ridotti (OR 0,54; IC 95% 0,39-0,75) e complicanze ridotte (OR 0,66; IC 95% 0,44-0,99); il posizionamento del piatto tibiale è più preciso. I punteggi di funzione migliorano di poco, circa 2-2,5 punti.", "Il limite: quasi tutti gli studi non assegnano i pazienti a caso e il controllo medio è di due anni.\nFonte: PubMed, PMID 42908376."], "pazienti": ["Protesi su una parte del ginocchio: una grande revisione ha confrontato l'intervento con il robot e quello senza.", "Con il robot ci sono stati meno reinterventi e meno complicanze, e l'impianto risulta posizionato in modo un po' più preciso.", "I pazienti sono stati seguiti in media per due anni: servono controlli più lunghi. La scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42908376."]}, "instagram": {"chir": ["UKA robotica: metanalisi", "34 studi, 68.196 protesi: revisioni OR 0,54 (IC 95% 0,39-0,75), complicanze OR 0,66 (IC 95% 0,44-0,99).", "27 studi su 34 non randomizzati, controllo di circa 2 anni.\nFonte: PubMed, PMID 42908376."], "misto": ["Protesi parziale e robot", "In 34 studi, con il robot meno reinterventi e meno complicanze, e un posizionamento più preciso del piatto tibiale.", "Quasi tutti gli studi non assegnano i pazienti a caso e durano circa due anni.\nFonte: PubMed, PMID 42908376."], "pazienti": ["Protesi su metà ginocchio: il robot", "Una revisione di 34 studi: meno reinterventi con il robot, ma servono controlli più lunghi.", "La scelta spetta al chirurgo, caso per caso.\nFonte: PubMed, PMID 42908376."]}, "reel": {"chir": ["[Testo a schermo] UKA robotica: revisioni OR 0,54", "34 studi; IC 95% 0,39-0,75.", "Quasi tutti non randomizzati.\nFonte: PubMed, PMID 42908376."], "misto": ["[Testo a schermo] Protesi parziale: il robot riduce i reinterventi?", "34 studi: meno reinterventi, controllo di due anni.", "Studi non casuali.\nFonte: PubMed, PMID 42908376."], "pazienti": ["[Testo a schermo] Protesi parziale e robot", "In 34 studi, meno reinterventi con il robot.", "Servono controlli più lunghi.\nFonte: PubMed, PMID 42908376."]}}};
var TAGS={"2": {"linkedin": "#Ortopedia #Protesi #Ginocchio", "instagram": "#ortopedia #ginocchio #protesi #protesimonocompartimentale #chirurgiarobotica #chirurgiadelginocchio #medicinabasatasulleprove #ortopediaticino #ticino #salute", "kw": "protesi monocompartimentale, protesi parziale ginocchio, chirurgia robotica ginocchio, ginocchio, ortopedia"}};
var NLB={"1": {"prof": ["LCA rotto, infiltrazione di cellule dal sangue e PRP: serie di 47 casi senza gruppo di controllo", "Serie di casi retrospettiva monocentrica (Indian J Orthop, 2026; Vienna, 47 pazienti): iniezione ecoguidata di cellule mononucleate autologhe e plasma ricco di piastrine nel legamento rotto, senza intervento. A 12 mesi IKDC 93,6 (IC 95% 92,4-94,8) e Lysholm 94,0 (IC 95% 92,7-95,3); una ricostruzione secondaria.", "Nota critica: nessun gruppo di controllo, stabilità non riportata nell'abstract, rotture parziali e complete mescolate; il recupero può riflettere la guarigione spontanea di casi selezionati."], "mix": ["Legamento crociato rotto curato con un'iniezione di cellule del proprio sangue: dati preliminari", "In 47 pazienti di un centro di Vienna, con rottura parziale o completa del legamento crociato anteriore, è stata iniettata nel legamento una preparazione di cellule e plasma ricavata dal loro sangue, senza operare. A un anno i punteggi di funzione erano molto alti e una sola persona è stata poi operata.", "Nota sul limite: non c'è un gruppo di confronto e l'abstract non riporta se il ginocchio fosse stabile ai controlli; il miglioramento potrebbe in parte essere spontaneo."], "paz": ["Legamento crociato rotto e iniezione di cellule del proprio sangue: uno studio preliminare", "Un centro di Vienna ha trattato 47 persone con una rottura del legamento crociato anteriore senza operarle, con un'iniezione preparata dal loro stesso sangue. Dopo un anno i punteggi di funzione erano molto buoni e una sola persona è stata poi operata.", "Nota rassicurante: è uno studio preliminare, senza gruppo di confronto; non è ancora un trattamento dimostrato e la scelta si discute con il chirurgo."], "kw": "legamento crociato anteriore, rottura LCA, PRP ginocchio, cellule dal sangue ginocchio"}, "2": {"prof": ["Protesi monocompartimentale robotica contro manuale: meno revisioni, ma prove in gran parte osservazionali", "Metanalisi di 34 studi (Orthop Surg, 2026; 68.196 protesi, controllo medio circa due anni). Revisioni OR 0,54 (IC 95% 0,39-0,75), complicanze OR 0,66 (IC 95% 0,44-0,99), pendenza tibiale più vicina all'obiettivo di 1,75° (IC 95% da 1,07 a 2,44), KSS ginocchio +2,49 (p=0,007), tempo operatorio +16,1 minuti.", "Nota critica: 27 studi su 34 non randomizzati, eterogeneità alta su pendenza tibiale e degenza, nessuna soglia MCID validata per la monocompartimentale."], "mix": ["Protesi parziale di ginocchio con il robot: meno reinterventi, ma a due anni di distanza", "In 34 studi su oltre 68.000 protesi che sostituiscono una sola parte del ginocchio, con il robot i reinterventi sono stati meno frequenti (OR 0,54; IC 95% 0,39-0,75) e le complicanze anche (OR 0,66; IC 95% 0,44-0,99); l'intervento dura circa sedici minuti di più.", "Nota sul limite: quasi tutti gli studi non assegnano i pazienti a caso e il controllo medio è di due anni, troppo breve per dire come dura l'impianto."], "paz": ["Protesi su una parte del ginocchio: che cosa dice la ricerca sul robot", "Una revisione di 34 studi ha confrontato l'intervento con il robot e quello senza, su oltre 68.000 protesi. Con il robot sono stati meno frequenti i reinterventi e le complicanze, e l'impianto è risultato posizionato in modo un po' più preciso.", "Nota rassicurante: gli studi seguono i pazienti in media per due anni; la scelta della tecnica dipende dal caso e si discute con il chirurgo."], "kw": "protesi parziale ginocchio, protesi monocompartimentale, robot ortopedia, chirurgia robotica"}, "3": {"prof": ["LCA cronicamente deficitario: più lesioni del menisco mediale rispetto alle rotture recenti", "Revisione sistematica di 22 studi (J Exp Orthop, 2026; 2.863 pazienti, 1.360 con LCA deficitario da oltre 6 mesi). Menisco mediale lesionato nel 50,3% contro il 36,0% delle rotture acute (p<0,001), sublussazione tibiale anteromediale +1,6 mm (p<0,001), nessuna differenza per il menisco laterale.", "Nota critica: confronto fra studi diversi e non fra gli stessi pazienti nel tempo, livello II-IV, intervalli non riportati nell'abstract; il ritardo si associa al danno, non lo dimostra come causa."], "mix": ["Crociato non operato per molto tempo: il menisco interno si danneggia più spesso", "In una revisione di 22 studi su quasi tremila pazienti, nelle ginocchia con legamento crociato rotto da oltre sei mesi il menisco interno risultava lesionato nel 50,3% dei casi, contro il 36,0% delle rotture recenti; per il menisco esterno non c'era differenza.", "Nota sul limite: gli studi confrontano gruppi diversi e non seguono lo stesso ginocchio nel tempo, quindi il ritardo è associato al danno ma non è dimostrato come causa."], "paz": ["Legamento crociato rotto e non curato: che cosa succede dopo molti mesi", "Una revisione di 22 studi ha visto che nelle ginocchia con il legamento crociato rotto da molto tempo il menisco interno è danneggiato più spesso rispetto alle rotture recenti. Il menisco esterno non mostrava differenze.", "Nota rassicurante: la revisione descrive un'associazione e non indica un momento oltre il quale non si possa più intervenire; il momento giusto si decide con il chirurgo."], "kw": "legamento crociato anteriore, menisco, lesione cronica LCA, risonanza ginocchio"}, "4": {"prof": ["Instabilità rotulea con patella alta nell'adolescente: MPFL con distalizzazione MPTL contro MPFL isolata", "Coorte retrospettiva comparativa (Eur J Trauma Emerg Surg, 2026; 28 adolescenti, età media 11,2 anni, 14 per braccio). Kujala finale 88,9 ± 4,5 con MPFL più MPTL contro 84,3 ± 5,1 con MPFL isolata; recidive 1/14 contro 2/14 (RR 2,00 per la sola MPFL; IC 95% 0,20-19,62, calcolo nostro).", "Nota critica: assegnazione non casuale (casi più gravi nel gruppo combinato), 14 per braccio e 1-2 eventi, follow-up 12-24 mesi, test fra i gruppi non riportati nell'abstract."], "mix": ["Rotula che si lussa in ragazzi con rotula alta: un secondo legamento sembra aiutare, ma lo studio è piccolo", "In 28 ragazzi di circa undici anni con rotula alta e lussazioni ripetute, la ricostruzione del legamento che stabilizza la rotula associata a un abbassamento della rotula ha dato punteggi di funzione un po' più alti (88,9 contro 84,3 su 100) e meno complicanze della sola ricostruzione.", "Nota sul limite: i ragazzi non sono stati assegnati a caso e i casi più gravi sono finiti nel gruppo combinato; con 14 pazienti per gruppo la differenza nelle recidive non si può né confermare né escludere."], "paz": ["Rotula che esce di sede in un ragazzo con rotula alta: uno studio su due modi di operare", "Uno studio egiziano su 28 ragazzi ha confrontato due interventi per la rotula che si lussa: la sola ricostruzione del legamento stabilizzatore oppure la stessa con in più un abbassamento della rotula. Entrambi i gruppi sono migliorati.", "Nota rassicurante: lo studio è piccolo e non assegna i ragazzi a caso; l'intervento si sceglie caso per caso con il chirurgo."], "kw": "lussazione rotula, instabilità rotulea, MPFL, ginocchio adolescente"}, "5": {"prof": ["Sutura meniscale: l'esercizio funzionale aggiuntivo migliora l'arco di movimento a sei mesi", "RCT di 96 pazienti (J Vis Exp, 2026; 48 per braccio): riabilitazione convenzionale con o senza esercizio funzionale dopo sutura meniscale. Arco di movimento a 6 mesi 134,36° ± 3,04° contro 127,62° ± 3,66° (differenza 6,74°; IC 95% 5,37-8,10); Lysholm a 6 mesi senza differenza.", "Nota critica: registrazione retrospettiva e molti esiti secondari (gli autori chiedono cautela), cecità dei valutatori non riportata nell'abstract, tipo di lesione e tecnica non descritti."], "mix": ["Dopo la sutura del menisco, un programma di esercizi più ricco recupera meglio il movimento del ginocchio", "In 96 pazienti operati di sutura del menisco, chi ha aggiunto esercizi funzionali alla riabilitazione standard ha recuperato un arco di movimento maggiore a sei mesi (circa 134 gradi contro 128); il punteggio di funzione a sei mesi non era diverso.", "Nota sul limite: lo studio è stato registrato dopo l'inizio e valuta molti esiti, per cui gli stessi autori chiedono prudenza; si sa poco di che tipo di lesione fosse."], "paz": ["Dopo la sutura del menisco: esercizi in più aiutano a piegare meglio il ginocchio", "In uno studio su 96 persone operate di sutura del menisco, chi ha fatto anche esercizi funzionali ha recuperato un movimento un po' più ampio dopo sei mesi. Il punteggio di funzione a sei mesi era simile nei due gruppi.", "Nota rassicurante: la riabilitazione si adatta al singolo caso con il fisioterapista; lo studio chiede conferme."], "kw": "sutura meniscale, riabilitazione menisco, esercizio dopo menisco, ginocchio"}, "6": {"prof": ["Pseudoaneurisma dopo artroscopia del ginocchio: 62 casi pubblicati, diagnosi mediana a 14 giorni", "Revisione sistematica di segnalazioni di casi (Cureus, 2026; 56 report, 62 pazienti): 25 dopo procedure meniscali (40,3%) e 19 dopo procedure sul LCA (30,6%); arteria poplitea in 26 (41,9%). Diagnosi mediana a 14 giorni (range 1-365), chirurgia vascolare aperta in 30 casi, embolizzazione in 14.", "Nota critica: solo casi pubblicati, nessun denominatore, quindi nessuna incidenza né rischio per procedura; bias di pubblicazione e follow-up breve in molti casi."], "mix": ["Dopo un'artroscopia del ginocchio, un gonfiore che non passa può nascondere un vaso lesionato", "Una revisione di 62 casi pubblicati di pseudoaneurisma, cioè una sacca di sangue che si forma da un vaso leso, dopo interventi artroscopici sul ginocchio: circa sette casi su dieci dopo menisco o legamento crociato, e in due casi su cinque l'arteria poplitea. La diagnosi è arrivata in mediana dopo 14 giorni.", "Nota sul limite: sono solo casi riportati, senza il numero totale di interventi, quindi la revisione non dice quanto sia frequente; serve a riconoscerlo."], "paz": ["Gonfiore del ginocchio che non passa dopo l'artroscopia: quando farlo controllare", "Dopo un'artroscopia del ginocchio, in rari casi si forma una sacca di sangue da un vaso leso. Una revisione di 62 casi pubblicati mostra che a volte compare dopo giorni o settimane, con gonfiore che ricompare o dolore sproporzionato.", "Nota rassicurante: è una complicanza rara; un gonfiore che non migliora o che ricompare va comunque segnalato al chirurgo."], "kw": "artroscopia ginocchio complicanze, gonfiore dopo artroscopia, arteria poplitea, menisco"}, "7": {"prof": ["Hockey professionistico: dopo ricostruzione del LCA il rendimento offensivo resta sotto i controlli a due anni", "Caso-controllo su 43 giocatori della NHL (J Exp Orthop, 2026): WAR/60 0,05 prima, 0,02 a un anno e 0,03 a due contro 0,04, 0,05 e 0,08 nei controlli appaiati; GAR offensivo/60 0,24, 0,13 e 0,18 contro 0,16, 0,27 e 0,37 (p=0,02 e p=0,01 dopo). Componente difensiva senza differenze.", "Nota critica: misura di prestazione di squadra e non di funzione del ginocchio, 43 casi, p riportati come 0,00, nessun dato su innesto o riabilitazione, esclusi i giocatori senza dati dopo la lesione."], "mix": ["Hockey su ghiaccio: dopo il legamento crociato i professionisti producono meno in attacco", "In 43 giocatori della lega nordamericana operati di legamento crociato, il rendimento offensivo due anni dopo era più basso rispetto ai giocatori di confronto (0,18 contro 0,37 su una misura di rendimento offensivo), mentre la parte difensiva non cambiava.", "Nota sul limite: la misura riflette il rendimento in squadra e non solo il ginocchio, e non si sa con quale tecnica siano stati operati."], "paz": ["Tornare all'hockey dopo la ricostruzione del crociato: che cosa mostra uno studio sui professionisti", "Uno studio su 43 giocatori professionisti di hockey operati al legamento crociato ha visto un rendimento in attacco più basso, a due anni, rispetto a giocatori simili non infortunati. La parte difensiva non è cambiata.", "Nota rassicurante: lo studio misura il rendimento in squadra e non lo stato del ginocchio; non indica come andrà il singolo paziente."], "kw": "hockey legamento crociato, ritorno allo sport, LCA professionisti, ginocchio sport"}, "8": {"prof": ["Risonanza a eco ultracorta dopo LCA: differenze del menisco laterale rispetto ai controlli", "Coorte prospettica (J Magn Reson Imaging, 2026): 30 scansioni di controllo e 19 + 13 di ricostruiti a 6-12 e oltre 12 mesi. UTE-Adiab-T1rho più alto nel menisco laterale (+5,60 ms a 6-12 mesi, q=0,035; +7,09 ms oltre 12 mesi, q=0,028); nessuna associazione con i PROM dopo correzione (q ≥ 0,383).", "Nota critica: confronto trasversale fra gruppi, innesto e lesioni associate non riportati nell'abstract, interazione gruppo per regione non significativa dopo correzione, nessuna validità clinica dimostrata."], "mix": ["Menisco dopo ricostruzione del crociato: una risonanza speciale vede differenze, ma non le collega ai sintomi", "In pazienti operati di legamento crociato, una risonanza con una sequenza ultracorta ha mostrato differenze di segnale nel menisco esterno rispetto a persone di controllo, a sei-dodici mesi e oltre un anno. Queste differenze non risultavano legate ai punteggi riferiti dai pazienti.", "Nota sul limite: si confrontano gruppi diversi in un solo momento, non gli stessi ginocchi prima e dopo, e il significato clinico del segnale è ancora da dimostrare."], "paz": ["Menisco dopo la ricostruzione del crociato: uno studio con una risonanza avanzata", "Uno studio ha usato una risonanza molto sensibile per guardare il menisco in persone operate al legamento crociato, e ha visto lievi differenze nel menisco esterno rispetto a persone non operate. Le differenze non erano legate ai sintomi riferiti.", "Nota rassicurante: è una misura di ricerca, non cambia il controllo che si fa oggi."], "kw": "menisco dopo crociato, risonanza magnetica ginocchio, ricostruzione LCA"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Indian J Orthop",h:"LCA rotto trattato senza intervento con cellule dal sangue e PRP: 47 casi, nessun gruppo di controllo",v:"Serie di casi retrospettiva di un centro di Vienna: 47 pazienti con rottura parziale o completa del LCA, trattati con una sola iniezione ecoguidata di cellule mononucleate autologhe e plasma ricco di piastrine, senza chirurgia. A 12 mesi IKDC 93,6 (IC 95% 92,4-94,8) e Lysholm 94,0 (IC 95% 92,7-95,3); una sola ricostruzione secondaria, nessuna nuova rottura. Nessun gruppo di controllo; la stabilità al controllo non è riportata nell'abstract.",ax:"Weninger, Herbst, Pfafl-Weninger, Reitböck",date:"ingresso PubMed ott 2026",meta:"serie di casi retrospettiva monocentrica, 47 pazienti, controllo a 12 mesi",pmid:'42894546',doi:'10.1007/s43465-026-01904-0',journal:"Indian journal of orthopaedics",authors:"Weninger P, Herbst A, Pfafl-Weninger V, Reitböck C",design:"Serie di casi retrospettiva in un centro di medicina dello sport di Vienna: pazienti consecutivi con rottura traumatica isolata, parziale o completa, del LCA confermata da esame clinico (Lachman, cassetto anteriore, pivot shift) e RM. Un'iniezione ecoguidata nel legamento di 8 mL di un preparato autologo da sangue venoso (circa 2-3 mL di cellule mononucleate concentrate in 6 mL di plasma con piastrine), carico completo subito, nessun tutore, fisioterapia standardizzata. Solo abstract.",pop:"47 pazienti, età media 28,1 anni (IC 95% 26,0-30,2); rotture parziali e complete; sesso, lesioni associate e distribuzione fra rotture parziali e complete non riportati nell'abstract.",results:"A 12 mesi: IKDC 93,6 (IC 95% 92,4-94,8), Lysholm 94,0 (IC 95% 92,7-95,3), VAS dolore 0,36 (IC 95% 0,19-0,53). Ritorno alla corsa dopo 2,19 settimane (IC 95% 1,93-2,45). Ritorno agli sport con pivot più rapido con guaina sinoviale integra (26,8 contro 33,2 settimane; test statistico non riportato). RM a 3 mesi: morfologia migliorata in tutti tranne un paziente. Nessuna infezione né nuova rottura; una ricostruzione secondaria. Punteggi di base e misure di stabilità al controllo non riportati nell'abstract.",concl:"Gli autori: una stimolazione biologica con cellule dal sangue può associarsi a recupero funzionale e a miglioramento radiologico in pazienti selezionati; servono studi prospettici controllati.",limits:"Nessun gruppo di controllo: il recupero può riflettere la guarigione spontanea di rotture parziali selezionate, che l'abstract stesso cita come possibile · Punteggi di base, stabilità strumentale e livello di attività prima della lesione non riportati nell'abstract · Casi consecutivi di un solo centro, con rotture parziali e complete insieme e preparato non standardizzato fra centri.",perte:"Arancione perché mette in discussione la ricostruzione come risposta al LCA rotto, ma non la sposta: senza controllo, senza stabilità misurata e con rotture parziali e complete mescolate, non dice nulla su ciò che fai tu (innesto quadricipitale più Lemaire onlay su LCA completo). Cosa fare: se un paziente ti porta questo trattamento, è un'ipotesi da studio e non un'alternativa documentata."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Orthop Surg",h:"Protesi monocompartimentale robotica contro manuale: meno revisioni, ma prove quasi tutte osservazionali",v:"Metanalisi di 34 studi (68.196 protesi: 22.585 robotiche, 45.611 manuali; controllo medio circa due anni). Revisioni OR 0,54 (IC 95% 0,39-0,75), complicanze OR 0,66 (IC 95% 0,44-0,99), pendenza tibiale più vicina all'obiettivo di 1,75° (IC 95% da 1,07 a 2,44). KSS ginocchio +2,49 (p=0,007), tempo operatorio +16,1 minuti. 27 studi su 34 non randomizzati; nessuna soglia MCID validata per la monocompartimentale.",ax:"Kanakala, Sugand, Tasong, Prashar, Shinmar, Namireddy, Gill",date:"ott 2026",meta:"metanalisi di 34 studi (7 RCT, 10 coorti prospettiche, 17 retrospettive), 68.196 protesi, controllo medio circa 2 anni",pmid:'42908376',doi:'10.1111/os.70424',journal:"Orthopaedic surgery",authors:"Kanakala S, Sugand K, Tasong J, Prashar A, Shinmar HS, Namireddy SR, Gill SS",design:"Revisione sistematica con metanalisi (PRISMA) a effetti casuali: PubMed, MEDLINE, Embase, Scopus e Web of Science fino a luglio 2025, studi comparativi fra UKA robotica e manuale. Rischio di bias con RoB 2 e ROBINS-I: dei 7 RCT due a basso rischio e cinque con dubbi; fra i non randomizzati la maggioranza a rischio moderato. Qualità dell'evidenza con OCEBM. Letto il testo completo (PMC, accesso aperto).",pop:"68.196 protesi monocompartimentali (45.611 manuali, 22.585 robotiche); età media 67,7 ± 9,0 anni (manuali) e 68,6 ± 8,5 (robotiche); controllo medio 23,9 ± 16,7 e 22,4 ± 16,9 mesi, da 1,5 a 95 mesi nei singoli studi. Piattaforma più frequente MAKO (22 studi), poi NAVIO (8); impianto manuale più frequente l'Oxford fase 3.",results:"Revisioni OR 0,54 (IC 95% 0,39-0,75; p<0,001; I² 40,2%); complicanze OR 0,66 (IC 95% 0,44-0,99; p=0,045; I² 39,6%). Tempo operatorio +16,1 minuti (IC 95% 10,8-21,4); degenza −0,2 giorni (IC 95% da −0,7 a 0,3), I² 98,4%. KSS ginocchio +2,49 (p=0,007), KSS funzione +2,33 (p=0,008), Oxford Knee Score SMC 1,06 (p=0,049). Pendenza tibiale: scostamento dall'obiettivo −1,75° (IC 95% da −2,44 a −1,07; I² 84,8%), rapporto delle DS 0,68 (IC 95% 0,54-0,84); angolo del componente tibiale e asse femoro-tibiale senza differenza significativa.",concl:"Gli autori: la UKA robotica può offrire vantaggi per precisione radiografica, complicanze, revisioni e risultati funzionali, ma l'alta eterogeneità degli studi e l'assenza di soglie MCID specifiche per la UKA ne limitano la rilevanza oggi; servono studi grandi, multicentrici e a lungo termine.",limits:"27 studi su 34 non randomizzati, fra cui due coorti da migliaia di protesi: selezione di pazienti e piattaforme può spiegare il vantaggio sulle revisioni, e un controllo medio di circa due anni è breve per una complicanza che emerge negli anni · Eterogeneità alta su pendenza tibiale e degenza; nessuna soglia MCID validata per la UKA (quelle della protesi totale sono 5,3-5,9 punti di KSS ginocchio): +2,5 non dimostra un beneficio avvertito dal paziente · Nessuna analisi per piattaforma o per impianto.",perte:"Verde: tocca la tua monocompartimentale. Il segnale c'è (meno revisioni, pendenza tibiale più precisa) ma viene da confronti in gran parte non randomizzati a due anni, e la differenza funzionale è piccola: non dimostra che il robot faccia durare di più l'impianto. Cosa fare: tienilo come base per rispondere a chi ti chiede del robot nella monocompartimentale, e rileggi la riduzione delle revisioni quando escono controlli a 5-10 anni."},{n:3,mono:"m-jeo",dot:"green",sec:"res",j:"J Exp Orthop",h:"LCA cronicamente rotto: più lesioni del menisco mediale e della cartilagine mediale che nelle rotture recenti",v:"Revisione sistematica di 22 studi (2.863 pazienti; 1.360 con LCA deficitario da oltre 6 mesi, tempo medio dal trauma alla RM 27,2 mesi). Lesioni del menisco mediale 50,3% contro 36,0% delle rotture recenti (p<0,001) e sublussazione tibiale anteromediale maggiore di 1,6 mm (p<0,001); nessuna differenza per il menisco laterale. La revisione associa il ritardo al danno, non può dire che lo causi.",ax:"Davtyan, Shah, Le, Pathak, Kolarska, Sritharan, Marks, Wasserstein",date:"ott 2026",meta:"revisione sistematica di 22 studi (livello II-IV), 2.863 pazienti, 1.360 con LCA deficitario da oltre 6 mesi",pmid:'42899038',doi:'10.1002/jeo2.70696',journal:"Journal of experimental orthopaedics",authors:"Davtyan A, Shah A, Le Q, Pathak A, Kolarska V, Sritharan P, Marks P, Wasserstein D",design:"Revisione sistematica su quattro banche dati dall'inizio al 19 gennaio 2025: studi primari di livello II-IV con RM in ginocchia con LCA deficitario da oltre 6 mesi; dati presentati in forma narrativa e, dove possibile, aggregati con confronto con le rotture acute. Valutazione del rischio di bias non riportata nell'abstract. Solo abstract.",pop:"22 studi, 2.863 pazienti; età media 27,9 anni (range delle medie 22,6-35,0), 68,3% uomini; 1.360 con LCA deficitario da oltre 6 mesi; tempo medio dall'infortunio alla RM 27,2 mesi (12,8-66,0 mesi in 11 studi).",results:"Menisco mediale lesionato nel 50,3% contro il 36,0% delle rotture acute (p<0,001), con incidenza che cresce linearmente col tempo; più lesioni del condilo femorale mediale e del piatto tibiale mediale (valori di p non riportati nell'abstract); sublussazione tibiale anteromediale +1,6 mm (p<0,001). Nessuna differenza per menisco laterale e sublussazione anterolaterale. Più buckling del LCP, attenuazione del legamento anterolaterale e frammentazione del LCA; meno edema osseo e versamento. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: nel LCA cronicamente deficitario si osserva più danno del compartimento mediale (menisco, cartilagine, sublussazione tibiale) e segni di attenuazione dei legamenti stabilizzatori.",limits:"Confronto fra studi diversi, non fra gli stessi pazienti nel tempo: la durata del ritardo può essere confusa con la selezione di chi resta non operato · Studi di livello II-IV, tempi dalla lesione molto diversi (12,8-66,0 mesi), intervalli di confidenza non riportati nell'abstract · La RM misura il danno e non la funzione: non dice quanti di questi ginocchi siano sintomatici.",perte:"Verde: non cambia la tua tecnica, conta per il consiglio sul timing. Il ritardo si associa a più danno mediale (menisco, cartilagine) ma non è dimostrato come causa e non indica una soglia di mesi. Cosa fare: usalo, con questa incertezza, nel colloquio con chi vuole rimandare la ricostruzione."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Eur J Trauma Emerg Surg",h:"Patella alta e instabilità rotulea in 28 adolescenti: MPFL con distalizzazione MPTL contro MPFL isolata",v:"Coorte retrospettiva egiziana (Zagazig), 28 adolescenti (età media 11,2 anni) con patella alta (indice di Caton-Deschamps > 1,2). Kujala finale 88,9 ± 4,5 con MPFL più MPTL (14) contro 84,3 ± 5,1 con MPFL isolata (14); recidive 1/14 contro 2/14. Assegnazione non casuale: i casi più gravi sono finiti nel gruppo combinato.",ax:"Salem, Ali, Metwally, Salem, El-Aidy, Sebaei, Hatem",date:"ott 2026",meta:"coorte retrospettiva comparativa, livello IV dichiarato, 28 adolescenti, 14 per braccio, 12-24 mesi",pmid:'42909499',doi:'10.1007/s00068-026-03365-4',journal:"European journal of trauma and emergency surgery",authors:"Salem H, Ali EMS, Metwally O, Salem M, El-Aidy S, Sebaei M, Hatem A",design:"Coorte retrospettiva comparativa in un centro (Zagazig, Egitto), maggio 2020-luglio 2025: tutti con ricostruzione dell'MPFL con semitendinoso a inserzione tibiale distale conservata, un tunnel obliquo transrotuleo e vite a interferenza femorale prossimale alla fisi; il gruppo B con in più la distalizzazione rotulea tramite il legamento patellotibiale mediale (MPTL), sutura transossea periostale. Gruppo A (14) MPFL isolata, gruppo B (14) MPFL più MPTL. Assegnazione non casuale. Controllo 12-24 mesi. Solo abstract.",pop:"28 adolescenti (9 maschi, 19 femmine), età media 11,2 ± 1,6 anni; patella alta (Caton-Deschamps > 1,2), almeno una lussazione, displasia trocleare Dejour A-B.",results:"Kujala 59,3 ± 8,3 → 84,3 ± 5,1 (MPFL isolata) e 56,2 ± 7,4 → 88,9 ± 4,5 (combinata); Lysholm 50,3 ± 7,5 → 74,7 ± 9,3 e 51,4 ± 7,6 → 87,4 ± 6,2. Caton-Deschamps 1,27 → 1,20 e 1,28 → 1,11. Complicanze 36% contro 21%. Recidive di instabilità (sublussazioni, trattate senza chirurgia) 2/14 contro 1/14 (RR 2,00; IC 95% 0,20-19,62, calcolo mio). Nessuna revisione chirurgica. Test statistici fra i gruppi non riportati nell'abstract.",concl:"Gli autori: l'MPFL con distalizzazione tramite MPTL dà un miglioramento funzionale maggiore, una correzione migliore della patella alta e meno complicanze rispetto all'MPFL isolata negli adolescenti con instabilità rotulea.",limits:"Assegnazione non casuale: i casi con patella alta più marcata e instabilità più grave sono stati trattati con la procedura combinata, quindi il confronto è sbilanciato · 14 pazienti per braccio e 1-2 eventi: non può escludere né un vantaggio né un danno della combinata · Controllo da 12 a 24 mesi in fisi aperte: la crescita residua e la tenuta della distalizzazione restano da vedere.",perte:"Verde: tocca la tua MPFL, ma il costrutto è diverso: tu usi ancore FiberTak onlay, qui semitendinoso con tunnel transrotuleo e vite, in ragazzi di 11 anni con fisi aperte (sotto la fascia che operi). Per la patella alta è un'ipotesi senza controllo casuale. Cosa fare: nella patella alta chiediti se la sola MPFL basti; questo studio non risponde."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"J Vis Exp",h:"Dopo la sutura meniscale, l'esercizio funzionale in più migliora l'arco di movimento a sei mesi (RCT di 96 pazienti)",v:"RCT cinese (Lanzhou), 96 pazienti operati di sutura meniscale: riabilitazione convenzionale (48) contro convenzionale più esercizio funzionale (48). A 6 mesi arco di movimento 134,36° ± 3,04° contro 127,62° ± 3,66° (differenza 6,74°; IC 95% 5,37-8,10). Lysholm a 6 mesi senza differenza; IKDC più alto con l'esercizio a 1 e 6 mesi. Registrazione dello studio retrospettiva.",ax:"Zhang, Yang, Yang",date:"ott 2026",meta:"RCT prospettico, 96 pazienti (48 per braccio), controllo a 6 mesi, analisi intention-to-treat",pmid:'42910733',doi:'10.3791/74035',journal:"Journal of visualized experiments : JoVE",authors:"Zhang J, Yang Z, Yang B",design:"RCT prospettico con sequenza di randomizzazione generata al computer, analisi intention-to-treat; pazienti operati da aprile 2023 a settembre 2024; esiti a basale, 1 e 6 mesi (Lysholm, IKDC, VAS, arco di movimento, PGE2, 5-HT, senso di posizione e di movimento a 60°, complicanze a 1 mese). Registrazione dello studio retrospettiva. Solo abstract.",pop:"96 pazienti sottoposti a sutura meniscale, 48 per braccio, tutti seguiti per 6 mesi; età, sesso, sede della lesione e tecnica di sutura non riportati nell'abstract.",results:"Arco di movimento a 6 mesi 134,36° ± 3,04° contro 127,62° ± 3,66° (differenza 6,74°; IC 95% 5,37-8,10; p aggiustato <0,001). Dopo correzione di Holm-Bonferroni: IKDC più alto con l'esercizio a 1 e 6 mesi, Lysholm più alto a 1 mese, VAS più bassa a entrambi i controlli; a 6 mesi nessuna differenza per Lysholm, PGE2, 5-HT e senso di movimento a 60°. Complicanze senza differenza significativa. Valori numerici di IKDC, Lysholm e VAS non riportati nell'abstract.",concl:"Gli autori: aggiungere l'esercizio funzionale può migliorare il recupero dopo la sutura meniscale, con l'evidenza più solida sull'arco di movimento; gli esiti secondari richiedono cautela per la registrazione retrospettiva e per i confronti multipli.",limits:"Registrazione retrospettiva e molti esiti secondari: gli stessi autori chiedono prudenza · Cecità dei valutatori non riportata nell'abstract; sul punteggio funzionale a 6 mesi (Lysholm) non c'è differenza · Tipo di lesione e tecnica di sutura non descritti nell'abstract: non si sa a chi si applichi.",perte:"Verde: non cambia la tua chirurgia, solo la riabilitazione dopo la sutura. Il vantaggio solido è di pochi gradi di arco di movimento; sul punteggio funzionale a 6 mesi non c'è differenza. Cosa fare: nessun cambiamento del protocollo; se aggiungi esercizio funzionale, è per l'articolarità e non per la funzione."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Cureus",h:"Pseudoaneurisma dopo artroscopia del ginocchio: 62 casi pubblicati, diagnosi mediana a 14 giorni",v:"Revisione sistematica di segnalazioni di casi (56 report, 62 pazienti): 25 dopo procedure meniscali (40,3%) e 19 dopo procedure sul LCA (30,6%); arteria poplitea lesa in 26 casi (41,9%). Diagnosi mediana a 14 giorni (range 1-365, 49 casi con intervallo noto). Frequenze descrittive di casi pubblicati: non stimano né incidenza né rischio.",ax:"Sack, Deneroff, Mohammed, Khau, Ellaham, Nichols",date:"ott 2026",meta:"revisione sistematica di segnalazioni di casi, 56 report, 62 pazienti",pmid:'42894765',doi:'10.7759/cureus.116501',journal:"Cureus",authors:"Sack EJ, Deneroff M, Mohammed Z, Khau A, Ellaham C, Nichols JW",design:"Revisione sistematica (PubMed, Embase, Scopus fino al 9 luglio 2026) dei casi riportati di pseudoaneurisma dopo artroscopia del ginocchio: 312 record, 54 report (60 casi) e, dopo l'audit delle citazioni, 56 report e 62 casi; un report non recuperabile non usato. Classificazione per procedura primaria mutuamente esclusiva. Solo abstract.",pop:"62 casi in 56 report: procedure meniscali 25 (40,3%), procedure sul LCA 19 (30,6%); vaso leso: arteria poplitea 26 (41,9%), rami genicolari mediali o inferiori 9 (14,5%). Età e sesso non riportati nell'abstract.",results:"Diagnosi vascolare mediana a 14 giorni (range 1-365; 49 casi con intervallo noto, 13 senza). Trattamento: chirurgia vascolare aperta 30, embolizzazione 14, iniezione di trombina ecoguidata 6, stent o altra riparazione endovascolare 5, sola osservazione 2, non specificato 4, nessun trattamento diretto 1. Esito: guarigione senza morbilità persistente in 42, morbilità neurologica o funzionale persistente o recupero incompleto in 4, follow-up breve o limitato in 10, esito non riportato in 6. Intervalli di confidenza non applicabili: solo frequenze di casi pubblicati.",concl:"Gli autori: sintomi ricorrenti o progressivi, un reperto pulsatile, alterazioni neurologiche o sintomi sproporzionati al decorso atteso dopo un'artroscopia devono far considerare l'imaging vascolare.",limits:"Solo casi pubblicati e nessun denominatore: non si può stimare incidenza né rischio per procedura (il 40% dopo menisco riflette anche quanto si opera il menisco) · Bias di pubblicazione e report eterogenei, follow-up breve o assente in 16 casi su 62 · Nessun confronto fra trattamenti.",perte:"Verde: riguarda ogni tua artroscopia, soprattutto menisco e LCA. Non cambia la tecnica: cambia la soglia d'allarme, perché un gonfiore che ricompare dopo giorni, con massa pulsante o deficit neurologico non è un ematoma di routine. Cosa fare: imaging vascolare prima di rioperare per «ematoma»."},{n:7,mono:"m-jeo",dot:"gray",sec:"res",j:"J Exp Orthop",h:"Hockey professionistico: dopo la ricostruzione del LCA il rendimento offensivo resta sotto i controlli a due anni",v:"Caso-controllo su 43 giocatori della NHL operati di LCA tra il 2008 e il 2022, confrontati con controlli appaiati per ruolo, anno di draft e rendimento. WAR/60 prima 0,05, a 1 e 2 anni 0,02 e 0,03 (p=0,01 e p=0,03 rispetto a prima) contro 0,05 e 0,08 nei controlli (p riportato come 0,00). Il calo è guidato dalla componente offensiva; la difensiva non differisce.",ax:"Hayes, Pulido, Carsen, Matache, Pickell",date:"ott 2026",meta:"caso-controllo retrospettivo, livello III dichiarato, 43 giocatori operati e controlli appaiati, 2 anni dopo la lesione",pmid:'42899301',doi:'10.1002/jeo2.70588',journal:"Journal of experimental orthopaedics",authors:"Hayes E, Pulido PG, Carsen S, Matache B, Pickell M",design:"Caso-controllo su dati pubblici di statistica avanzata (NHL Injury Viz): giocatori operati di ricostruzione del LCA 2008-2022, esclusi multiligamentosi, rotture ripetute, revisioni, portieri e altre lesioni operate; confronto fra 1 anno prima e 2 dopo, con controlli appaiati per ruolo, anno di draft e prestazione dell'anno indice. Esito primario WAR/60 (wins above replacement per 60 minuti), secondari GAR offensivo e difensivo per 60. Test appaiati e di Wilcoxon. Solo abstract.",pop:"61 rotture del LCA identificate, 43 eleggibili; numero e caratteristiche dei controlli, età, tecnica operatoria e innesto non riportati nell'abstract.",results:"WAR/60: 0,05 prima, 0,02 a 1 anno e 0,03 a 2 anni nei casi (p=0,01 e p=0,03 rispetto a prima) contro 0,04, 0,05 e 0,08 nei controlli (p=0,50 prima; poi p riportato come 0,00 a 1 e 2 anni rispetto ai casi). GAR offensivo/60: 0,24, 0,13 e 0,18 nei casi contro 0,16, 0,27 e 0,37 nei controlli (p=0,83 prima; p=0,02 e p=0,01 dopo). GAR difensivo senza differenze significative. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: la ricostruzione del LCA si associa a una prestazione significativamente più bassa rispetto ai controlli, guidata dalla componente offensiva.",limits:"Misura di prestazione di squadra influenzata da minuti, compagni e ruolo, non di funzione del ginocchio; p riportati come 0,00 e nessun intervallo · 43 casi e nessun dato su tecnica, innesto, riabilitazione o criteri di rientro: non si sa che cosa spieghi il calo · Esclusi i giocatori senza dati prima o dopo la lesione: chi smette di giocare dopo l'operazione non compare, quindi il calo reale può essere sottostimato.",perte:"Bianco: non tocca una tua tecnica. Per un paziente che gioca a hockey dà un ordine di grandezza del rendimento dopo la ricostruzione del LCA, ma misura la squadra e non il ginocchio. Cosa fare: nessuna azione; non è un criterio di rientro."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"J Magn Reson Imaging",h:"Risonanza a eco ultracorta dopo la ricostruzione del LCA: differenze regionali del menisco, soprattutto laterale",v:"Coorte prospettica (San Diego): 30 scansioni di controllo e 19 + 13 di ricostruiti a 6-12 e oltre 12 mesi. UTE-Adiab-T1rho più alto nel menisco laterale (+5,60 ms a 6-12 mesi, q=0,035; +7,09 ms oltre 12 mesi, q=0,028). Nessuna associazione con i PROM dopo correzione (q ≥ 0,383): una misura di ricerca, non un marcatore clinico.",ax:"Wu, Moazamian, Kim, Wang, Cheraghi, Mohammadi, Malhi, Athertya, Ma, Chang, Yang, Jerban, Bukata, Chung, Du",date:"ott 2026",meta:"coorte prospettica longitudinale, 62 scansioni (30 controlli, 19 e 13 ricostruiti), RM 3T",pmid:'42908189',doi:'10.1002/jmri.70600',journal:"Journal of magnetic resonance imaging : JMRI",authors:"Wu J, Moazamian D, Kim D, Wang J, Cheraghi MA, Mohammadi HS, Malhi B, Athertya J, Ma Y, Chang E, Yang C, Jerban S, Bukata S, Chung C, Du J",design:"Coorte prospettica longitudinale con RM 3T 3D a eco ultracorta (UTE): T1rho adiabatico e frazione macromolecolare da magnetization transfer; valori estratti da quattro regioni meniscali da un lettore in cieco, ridelineazione in cieco su un sottogruppo; modelli lineari a effetti misti e correzione FDR di Benjamini-Hochberg; PROM IKDC, KOOS, WOMAC. Solo abstract.",pop:"30 scansioni di controllo e 19 + 13 scansioni di ricostruiti a 6-12 e oltre 12 mesi; età medie 34,5, 34,5 e 37,2 anni; sesso F/M 15/15, 9/10 e 8/5. Numero di partecipanti distinti, innesto e tecnica non riportati nell'abstract.",results:"UTE-Adiab-T1rho più alto rispetto ai controlli nella regione LAM a 6-12 mesi (+5,60 ms; q=0,035) e oltre 12 mesi (+7,09 ms; q=0,028) e nella LPM oltre 12 mesi (+6,35 ms; q=0,035). UTE-MMF più bassa nella LPM (−3,56 punti percentuali, q=0,028; −3,10, q=0,049). Nessun contrasto fra 6-12 e oltre 12 mesi né associazione MRI-PROM sopravvive alla correzione (tutti q ≥ 0,383). Interazioni gruppo per regione non significative dopo correzione. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: le mappe quantitative UTE identificano differenze meniscali regionali dopo la ricostruzione del LCA, concentrate nelle regioni laterali; i PROM erano peggiori nei ricostruiti, senza differenza fra le finestre postoperatorie dopo correzione.",limits:"Confronto fra gruppi diversi in un solo momento, non gli stessi ginocchi prima e dopo: non si sa se la differenza preceda o segua l'intervento · 62 scansioni; innesto e lesioni meniscali concomitanti non riportati nell'abstract; interazione gruppo per regione non significativa dopo correzione · Nessuna associazione con gli esiti clinici: il segnale non è un marcatore clinico.",perte:"Bianco: non tocca la tua pratica; è una misura di ricerca senza correlazione con gli esiti. Cosa fare: nulla."}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Sabato 24 ottobre. Oggi otto lavori, nessuna scheda rossa e una arancione. Nessun richiamo di dispositivi nuovo, nessuna linea guida o consensus nuovo che tocchi la tua pratica e nessuna ritrattazione che ti riguardi. La scheda arancione è una serie di casi di Vienna: quarantasette pazienti con il crociato anteriore rotto, trattati senza intervento con un'iniezione di cellule dal sangue e plasma ricco di piastrine; a dodici mesi i punteggi sono molto alti, ma non c'è un gruppo di controllo e l'abstract non riporta la stabilità. Il lavoro del giorno è una metanalisi sulla protesi monocompartimentale robotica contro manuale: trentaquattro studi, oltre sessantottomila protesi, controllo medio di circa due anni; ho letto il testo completo. Con il robot le revisioni sono meno frequenti, odds ratio zero virgola cinquantaquattro, intervallo di confidenza da zero virgola trentanove a zero virgola settantacinque, e le complicanze anche, zero virgola sessantasei; il piatto tibiale è più vicino alla pendenza pianificata. Ma ventisette studi su trentaquattro non sono randomizzati, l'eterogeneità è alta e non esiste una soglia di differenza clinicamente importante specifica per la monocompartimentale: il segnale c'è, la prova che l'impianto duri di più no. Poi cinque lavori sulla tua pratica. Una revisione sul crociato cronicamente rotto: il menisco mediale è lesionato nel cinquanta virgola tre per cento dei casi, contro il trentasei virgola zero delle rotture recenti. Un confronto retrospettivo su ventotto adolescenti con rotula alta: legamento patellofemorale mediale con o senza abbassamento della rotula, risultati migliori con la procedura combinata, ma gruppi non casuali e quattordici pazienti per braccio. Uno studio randomizzato su novantasei suture meniscali: l'esercizio funzionale aggiuntivo migliora l'arco di movimento di sei virgola settantaquattro gradi, mentre il punteggio di funzione a sei mesi non cambia. Una revisione di sessantadue casi di pseudoaneurisma dopo artroscopia, con diagnosi mediana a quattordici giorni, circa sette su dieci dopo menisco o crociato. Due lavori bianchi: il rendimento dei giocatori di hockey della NHL dopo la ricostruzione del crociato e una risonanza a eco ultracorta del menisco dopo la ricostruzione. Tensioni: nessuna si è mossa oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Sabato ventiquattro ottobre. Otto lavori, nessuna scheda rossa e una arancione. Nessun richiamo nuovo, nessun consensus nuovo sulla tua pratica e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Una metanalisi sulla protesi monocompartimentale robotica contro manuale: trentaquattro studi, oltre sessantottomila protesi, controllo medio di circa due anni."}, {"chi": "B", "t": "E che cosa trova?"}, {"chi": "A", "t": "Con il robot meno revisioni, odds ratio zero virgola cinquantaquattro, intervallo da zero virgola trentanove a zero virgola settantacinque, e meno complicanze, zero virgola sessantasei. La pendenza tibiale è più vicina a quella pianificata."}, {"chi": "B", "t": "Quindi il robot fa durare di più l'impianto?"}, {"chi": "A", "t": "Non lo dimostra. Ventisette studi su trentaquattro non sono randomizzati, l'eterogeneità è alta e il controllo è breve. Anche i punteggi di funzione salgono di poco, sotto le soglie note per la protesi totale."}, {"chi": "B", "t": "Per la mia monocompartimentale che cosa cambia?"}, {"chi": "A", "t": "Niente da cambiare: è una base per rispondere a chi ti chiede del robot. La riduzione delle revisioni va riletta con controlli a cinque-dieci anni."}, {"chi": "B", "t": "E la scheda arancione?"}, {"chi": "A", "t": "Un'iniezione di cellule dal sangue e plasma ricco di piastrine nel crociato rotto, senza intervento: quarantasette pazienti di Vienna, punteggi molto alti a dodici mesi. Ma nessun gruppo di controllo e nessuna stabilità riportata nell'abstract."}, {"chi": "B", "t": "Quindi non è un'alternativa alla ricostruzione."}, {"chi": "A", "t": "No, è un'ipotesi da studio. Poi una revisione sul crociato cronico, con il menisco mediale lesionato più spesso, e una sullo pseudoaneurisma dopo artroscopia, con diagnosi mediana a quattordici giorni."}, {"chi": "B", "t": "Le tensioni?"}, {"chi": "A", "t": "Nessuna si è mossa oggi."}];
